/**
 * Asks the carrier for the status of each shipment, and returns a Map from tracking number to
 * status. Shipments already 'delivered' are not asked about, since that status never changes; they
 * keep it in the result. Each tracking number is asked about once.
 */
export async function refreshTracking(shipments, transport) {
  const statuses = new Map();
  const toAsk = new Set();
  for (const shipment of shipments) {
    if (shipment.status === 'delivered') statuses.set(shipment.trackingNumber, 'delivered');
    else toAsk.add(shipment.trackingNumber);
  }
  const numbers = [...toAsk].filter((number) => statuses.get(number) !== 'delivered');

